import random
from typing import List

# Data type: big-endian integer bytes for ptls_buffer_push_asn1_ubigint
_MAX_LEN = 512

def _randbytes(rng: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    out = bytearray()
    while len(out) < n:
        chunk = min(8, n - len(out))
        val = rng.getrandbits(8 * chunk)
        out.extend(val.to_bytes(chunk, 'big'))
    return bytes(out)

def _biased_lengths() -> List[int]:
    return [
        0, 1, 2, 3, 7, 8, 15, 16, 17, 31, 32, 33,
        63, 64, 65, 127, 128, 129, 255, 256, 257, 511, 512
    ]

def _make_candidate(rng: random.Random) -> bytes:
    strategies = [
        "zero",            # empty -> stub replaces with 0x00
        "single_byte",
        "leading_zeroes",
        "no_leading_zero",
        "pattern",
        "random_len_random_bytes",
        "max_len",
        "small_ints",
        "top_bit_set",
    ]
    weights = [5, 10, 10, 25, 10, 5, 15, 20, 10]
    strat = rng.choices(population=strategies, weights=weights, k=1)[0]

    if strat == "zero":
        return b""  # will become 0x00 in stub

    if strat == "single_byte":
        return bytes([rng.randrange(0, 256)])

    if strat == "leading_zeroes":
        lz = rng.randrange(1, 9)
        tail_len = max(1, rng.randrange(1, 33))
        tail = _randbytes(rng, tail_len)
        if all(b == 0 for b in tail):
            tail = bytearray(tail)
            tail[rng.randrange(0, len(tail))] = rng.randrange(1, 256)
            tail = bytes(tail)
        return b"\x00" * lz + tail

    if strat == "no_leading_zero":
        length = rng.choice(_biased_lengths())
        if length == 0:
            length = 1
        b0 = rng.randrange(1, 256)
        rest = _randbytes(rng, length - 1)
        return bytes([b0]) + rest

    if strat == "pattern":
        patterns = [
            b"\x00" * 16,
            b"\xff" * 16,
            b"\x01" * 16,
            bytes([0x80]) + b"\x00" * 15,
            bytes([0x7f]) * 16,
            b"\xaa\x55" * 16,
        ]
        base = rng.choice(patterns)
        target = rng.choice([len(base), 32, 64, 128, 256, 512])
        data = (base * ((target + len(base) - 1)//len(base)))[:target]
        for _ in range(rng.randrange(0, 4)):
            i = rng.randrange(0, len(data))
            v = rng.randrange(0, 256)
            data = data[:i] + bytes([v]) + data[i+1:]
        return data

    if strat == "random_len_random_bytes":
        length = rng.choice(_biased_lengths())
        if length == 0:
            return b""
        return _randbytes(rng, length)

    if strat == "max_len":
        data = bytearray(_randbytes(rng, _MAX_LEN))
        if rng.random() < 0.7 and _MAX_LEN > 0:
            data[0] = max(1, data[0])
        return bytes(data)

    if strat == "small_ints":
        values = [0, 1, 2, 127, 128, 255, 256, 257, 65535, 65536]
        v = rng.choice(values)
        if v == 0:
            minimal = b"\x00"
        else:
            blen = (v.bit_length() + 7) // 8
            minimal = v.to_bytes(blen, 'big')
        if rng.random() < 0.5:
            return minimal
        lz = rng.randrange(1, 8)
        return b"\x00" * lz + minimal

    if strat == "top_bit_set":
        length = rng.choice([1, 2, 3, 8, 16, 33, 64, 128, 256, 512])
        if length == 0:
            length = 1
        first = rng.randrange(0x80, 0x100)
        rest = _randbytes(rng, length - 1)
        return bytes([first]) + rest

    return _randbytes(rng, rng.randrange(0, _MAX_LEN + 1))


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    data = _make_candidate(rng)
    if len(data) > _MAX_LEN:
        data = data[:_MAX_LEN]
    if len(data) > 4096:
        data = data[:4096]
    return data

import random
import base64
import textwrap
from typing import List, Tuple

# Generator for PEM files containing one or more valid PEM blocks (CERTIFICATE, PRIVATE KEY, EC PRIVATE KEY, RSA PRIVATE KEY, PUBLIC KEY, X509 CERTIFICATE)
# The content aims to be syntactically valid PEM with plausible headers and base64 payloads, so ptls_load_pem_objects can find objects.

PEM_LABELS = [
    "CERTIFICATE",
    "X509 CERTIFICATE",
    "PRIVATE KEY",
    "EC PRIVATE KEY",
    "RSA PRIVATE KEY",
    "PUBLIC KEY",
]

# Helper: produce base64 text with 64-char wrapped lines
def _b64_wrap(b: bytes) -> str:
    enc = base64.b64encode(b).decode("ascii")
    return "\n".join(textwrap.wrap(enc, 64)) + "\n"

# Helper: generate random DER-like binary payload of target size range
def _rand_bytes(rng: random.Random, min_len: int, max_len: int) -> bytes:
    n = rng.randint(min_len, max_len)
    return bytes(rng.getrandbits(8) for _ in range(n))

# Helper: create a PEM block with optional headers
def _make_pem_block(rng: random.Random, label: str, body_bytes: bytes, add_headers: bool) -> str:
    lines: List[str] = []
    lines.append(f"-----BEGIN {label}-----\n")
    if add_headers:
        # Insert a few plausible header lines (ignored by many parsers, but common in PEM)
        hdrs = []
        if rng.random() < 0.7:
            # Content-Type-like header
            hdrs.append("Proc-Type: 4,ENCRYPTED\n" if rng.random() < 0.3 else "Proc-Type: 4,UNPROTECTED\n")
        if rng.random() < 0.7:
            # DEK-Info like header with hex IV
            algo = rng.choice(["AES-256-CBC", "AES-128-CBC", "DES-EDE3-CBC", "AES-256-GCM"])
            ivlen = rng.choice([16, 8, 12])
            iv = bytes(rng.getrandbits(8) for _ in range(ivlen)).hex().upper()
            hdrs.append(f"DEK-Info: {algo},{iv}\n")
        # Headers terminated by a blank line
        lines.extend(hdrs)
        lines.append("\n")
    lines.append(_b64_wrap(body_bytes))
    lines.append(f"-----END {label}-----\n")
    return "".join(lines)

# Generate plausible payload sizes depending on label
def _payload_for_label(rng: random.Random, label: str) -> bytes:
    # Choose sizes typical for each object, but allow variability
    if label in ("CERTIFICATE", "X509 CERTIFICATE"):
        # DER-encoded X.509 typically 600-2000 bytes; keep within bound
        return _rand_bytes(rng, 400, 1800)
    if label in ("PRIVATE KEY",):
        # PKCS#8 DER often 800-2000 bytes
        return _rand_bytes(rng, 600, 1600)
    if label in ("EC PRIVATE KEY",):
        # SEC1 EC private key often 120-200 bytes
        return _rand_bytes(rng, 100, 300)
    if label in ("RSA PRIVATE KEY",):
        # PKCS#1 RSA private key often 600-1700 bytes
        return _rand_bytes(rng, 600, 1600)
    if label in ("PUBLIC KEY",):
        # SubjectPublicKeyInfo often 150-400 bytes
        return _rand_bytes(rng, 120, 500)
    # Fallback
    return _rand_bytes(rng, 64, 256)

# Optionally concatenate multiple PEM blocks, some with different labels
def _make_pem_file(rng: random.Random) -> str:
    blocks: List[str] = []
    # Choose 1..5 blocks, bias towards 2-3
    count = rng.choices([1, 2, 3, 4, 5], weights=[2, 4, 4, 2, 1])[0]
    # Optionally include mixed labels to exercise selection logic
    labels = [rng.choice(PEM_LABELS) for _ in range(count)]

    for i, label in enumerate(labels):
        # Payload
        payload = _payload_for_label(rng, label)
        # Randomly add small prefix/suffix padding inside DER-ish content to vary base64
        if rng.random() < 0.2:
            payload = bytes([0x30]) + payload  # ASN.1 SEQUENCE leader-like
        if rng.random() < 0.2:
            payload = payload + bytes([0x00])
        add_headers = rng.random() < 0.5
        block = _make_pem_block(rng, label, payload, add_headers)
        blocks.append(block)
        # Optional whitespace between blocks
        if rng.random() < 0.4:
            blocks.append("\n")
    # Optionally prepend a comment banner to simulate real PEM files
    if rng.random() < 0.3:
        banner = ["# -----BEGIN GENERATED PEM FILE-----\n"]
        if rng.random() < 0.5:
            banner.append("# Created by fuzzer seed generator\n\n")
        return "".join(banner) + "".join(blocks)
    return "".join(blocks)

# Public API

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Build a PEM file not exceeding 4096 bytes. If too large, trim by reducing block count or payload size.
    pem = _make_pem_file(rng)

    # Enforce maximum size by shrinking: remove intermediate whitespace and, if still too big, truncate extra blocks.
    if len(pem) > 4096:
        # Try removing blank lines
        pem = "\n".join([line for line in pem.splitlines() if line.strip() != ""]) + "\n"
    if len(pem) > 4096:
        # Keep only first N blocks until size fits
        parts: List[str] = []
        size = 0
        for blk in pem.split("-----BEGIN "):
            if not blk:
                continue
            candidate = ("-----BEGIN " + blk)
            if size + len(candidate) > 4096:
                break
            parts.append(candidate)
            size += len(candidate)
        pem = "".join(parts)
        # Ensure file ends with newline
        if not pem.endswith("\n"):
            pem += "\n"
    # Final safety: hard cut if still oversized (should be rare)
    if len(pem) > 4096:
        pem = pem[:4095] + "\n"

    return pem.encode("ascii")
